"""Independent exhaustive oracle for the small synthetic R43 input, not a product."""
import csv
import io
import json
from pathlib import Path
from v2_volunteer_schedule import FILES


def rows(text):
    return list(csv.DictReader(io.StringIO(text)))


def minute(value):
    hour, minutes = map(int, value.split(':'))
    return hour*60 + minutes


def maximum(people_text, availability_text, shifts_text):
    people = {p['id']: p for p in rows(people_text)}
    availability = rows(availability_text)
    shifts = rows(shifts_text)
    slots = [s for s in shifts for _ in range(int(s['required']))]
    best = []
    chosen = []
    used = {key: 0 for key in people}
    def visit(index):
        nonlocal best
        if len(chosen)+len(slots)-index <= len(best):
            return
        if index == len(slots):
            best = chosen.copy()
            return
        shift = slots[index]
        start, end = minute(shift['start']), minute(shift['end'])
        duration = end-start
        for pid, person in people.items():
            if shift['role'] not in person['roles'].split(';'):
                continue
            if used[pid]+duration > float(person['max_hours'])*60:
                continue
            if not any(a['person_id'] == pid and a['date'] == shift['date'] and minute(a['start']) <= start and minute(a['end']) >= end for a in availability):
                continue
            if any(p == pid and prior['date'] == shift['date'] and start < minute(prior['end']) and end > minute(prior['start']) for p, prior in chosen):
                continue
            chosen.append((pid, shift))
            used[pid] += duration
            visit(index+1)
            used[pid] -= duration
            chosen.pop()
        visit(index+1)
    visit(0)
    return {'filled': len(best), 'needed': len(slots), 'assignments': [{'person_id': pid, 'shift_id': s['id']} for pid, s in best]}


def validate(plan, people_text, availability_text, shifts_text):
    """Check normalized exported assignments independently of product code; fixtures cover one week."""
    people = {p['id']: p for p in rows(people_text)}
    shifts = {s['id']: s for s in rows(shifts_text)}
    availability = rows(availability_text)
    assigned = []
    used = {pid: 0 for pid in people}
    counts = {sid: 0 for sid in shifts}
    pairs = set()
    for entry in plan:
        pid, sid = entry['person_id'], entry['shift_id']
        assert pid in people and sid in shifts, 'Unknown person or shift'
        assert (pid,sid) not in pairs, 'Same person counted twice in a shift'
        pairs.add((pid,sid))
        s, p = shifts[sid], people[pid]
        start, end = minute(s['start']), minute(s['end'])
        assert s['role'] in p['roles'].split(';'), 'Unconfirmed role'
        assert any(a['person_id']==pid and a['date']==s['date'] and minute(a['start'])<=start and minute(a['end'])>=end for a in availability), 'Not available for complete shift'
        assert not any(other_pid==pid and other['date']==s['date'] and start<minute(other['end']) and end>minute(other['start']) for other_pid,other in assigned), 'Overlapping assignment'
        used[pid] += end-start
        assert used[pid] <= float(p['max_hours'])*60, 'Weekly hours exceeded'
        counts[sid] += 1
        assert counts[sid] <= int(s['required']), 'Shift capacity exceeded'
        assigned.append((pid,s))
    return {'filled':len(assigned),'gaps':{sid:int(s['required'])-counts[sid] for sid,s in shifts.items() if counts[sid]<int(s['required'])}}


def main():
    normal = FILES['可用时间.csv']
    withdrawal = '\n'.join(line for line in normal.splitlines() if not line.startswith('v05,'))+'\n'
    extra = FILES['岗位.csv']+'s07,2026-10-17,10:00,12:00,引导,1\n'
    result = {name: maximum(FILES['人员.csv'], availability, shifts) for name, availability, shifts in [('initial',normal,FILES['岗位.csv']),('withdrawal',withdrawal,FILES['岗位.csv']),('overlap',normal,extra)]}
    assert result['initial']['filled'] == 7 and result['initial']['needed'] == 7
    assert result['withdrawal']['filled'] == 6 and result['withdrawal']['needed'] == 7
    assert result['overlap']['filled'] == 7 and result['overlap']['needed'] == 8
    assert {'v01','v03'} <= {a['person_id'] for a in result['initial']['assignments']}
    for name, availability, shifts in [('initial',normal,FILES['岗位.csv']),('withdrawal',withdrawal,FILES['岗位.csv']),('overlap',normal,extra)]:
        checked = validate(result[name]['assignments'],FILES['人员.csv'],availability,shifts)
        assert checked['filled'] == result[name]['filled']
    for bad in [result['initial']['assignments']+[result['initial']['assignments'][0]], [{'person_id':'v03','shift_id':'s01'}], result['initial']['assignments']+[{'person_id':'v01','shift_id':'s07'}]]:
        try:
            validate(bad,FILES['人员.csv'],normal,extra)
        except AssertionError:
            pass
        else:
            raise AssertionError('Invalid schedule accepted by independent validator')
    out = Path(__file__).resolve().parent.parent/'outputs/intent-compiler-v2/volunteer-schedule-r43'
    if out.exists():
        (out/'fixture-oracle.json').write_text(json.dumps(result,ensure_ascii=False,indent=2),encoding='utf-8')
    print(json.dumps(result,ensure_ascii=False))


if __name__ == '__main__':
    main()

